package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import org.json.*;
public final class AudioManagerActivity extends AppScreen {
 private String tab="phone";public void onCreate(Bundle b){super.onCreate(b);if(getIntent().getBooleanExtra("cleanup",false))tab="cleanup";render();}
 private void render(){frame("原始音频管理");button(body,"‹ 返回",this::finish);body.addView(title("原始音频管理",24));body.addView(text("手机与手表分别管理。手表仅自动清理已传到手机、已整理且超过 7 天的片段；未同步或未整理原件继续保留。",13,MUTED));HorizontalScrollView fs=new HorizontalScrollView(this);fs.setHorizontalScrollBarEnabled(false);LinearLayout filters=row();fs.addView(filters);body.addView(fs);for(String id:new String[]{"phone","cleanup","watch","commands"})button(filters,id.equals("phone")?"手机":id.equals("cleanup")?"待清理":id.equals("watch")?"手表":"删除指令",()->{tab=id;render();});try{if(tab.equals("phone")||tab.equals("cleanup")){JSONArray rows=store.rows("SELECT id,title,created,duration,bytes,path,transcript,speech_json,analysis,vad_map FROM audio ORDER BY created DESC");for(int i=0;i<rows.length();i++){JSONObject a=rows.getJSONObject(i);if(tab.equals("cleanup")&&(!AudioReview.suggested(a)||a.optString("path").isEmpty()))continue;LinearLayout c=card(body);c.addView(rawTitle(a.getString("title"),17));c.addView(text(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",AppLanguage.locale(this)).format(new java.util.Date(a.getLong("created")))+" · "+String.format(java.util.Locale.ROOT,"%.1f MB",a.getLong("bytes")/1048576.0),12,MUTED));c.addView(text(a.optString("path").isEmpty()?"手机音频已删除，整理结果保留":a.optString("speech_json").isEmpty()?"尚未完成离线整理":"已整理",12,SAGE));if(AudioReview.suggested(a)&&!a.optString("path").isEmpty()){c.addView(text("这段录音可能可以清理",14,SAGE));AudioReview.explain(this,c,a);c.addView(text("请先试听，再核对是否删除。",12,MUTED));}button(c,"回看记录",()->openRecord(a.optString("id")));button(c,"删除与存储位置",()->AudioActions.show(this,a.optString("id"),this::render));}if(rows.length()==0)body.addView(text("暂无手机录音",14,MUTED));if(tab.equals("cleanup"))body.addView(text("仅列出本地未检出人声或 LLM 建议清理的片段；不会自动删除。",13,MUTED));}else if(tab.equals("watch")){long at=getSharedPreferences("device-sync",0).getLong("archive_sync_at",0);body.addView(text(at==0?"尚未获取手表清单，请在手表点立即同步":("清单更新时间："+new java.text.SimpleDateFormat("MM-dd HH:mm",AppLanguage.locale(this)).format(new java.util.Date(at))),12,MUTED));JSONArray rows=store.rows("SELECT * FROM watch_files WHERE device=? AND present=1 ORDER BY created DESC",WatchArchive.device(this));for(int i=0;i<rows.length();i++){JSONObject f=rows.getJSONObject(i);LinearLayout c=card(body);c.addView(rawTitle(f.getString("name"),15));c.addView(text(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",AppLanguage.locale(this)).format(new java.util.Date(f.optLong("created")))+" · "+String.format(java.util.Locale.ROOT,"%.1f MB",f.optLong("bytes")/1048576.0),12,MUTED));boolean pending=store.rows("SELECT id FROM watch_commands WHERE device=? AND name=? AND sha=? AND status='pending'",f.getString("device"),f.getString("name"),f.getString("sha")).length()>0;button(c,pending?"等待手表确认删除":"删除手表原件",()->{if(pending)return;new LocalDialog(this).setTitle("删除手表原件？").setMessage("手机副本保留；下次手表同步执行。尚未传到手机的文件也会被删除，请核对后确认。").setPositiveButton("删除",(d,w)->background(()->WatchArchive.requestFile(store,f.getString("device"),f.getString("name"),f.getString("sha")),this::render)).setNegativeButton("取消",null).show();});}if(rows.length()==0)body.addView(text("清单中没有已完成的手表片段",14,MUTED));}else{JSONArray commands=store.rows("SELECT * FROM watch_commands ORDER BY created DESC LIMIT 300");for(int i=0;i<commands.length();i++){JSONObject cmd=commands.getJSONObject(i);LinearLayout c=card(body);c.addView(rawTitle(cmd.optString("name"),15));String status=cmd.optString("status");c.addView(text(status.equals("pending")?"等待下次手表同步":status.equals("deleted")?"手表已确认删除":status.equals("absent")?"手表已确认文件不存在":status.equals("mismatch")?"文件身份不符，未删除":"手表删除失败",13,SAGE));if(status.equals("pending"))button(c,"取消删除指令",()->{store.getWritableDatabase().delete("watch_commands","id=? AND status='pending'",new String[]{cmd.optString("id")});render();});else if(status.equals("failed"))button(c,"重试删除",()->{store.update("watch_commands",cmd.optString("id"),"status","pending");render();});}if(commands.length()==0)body.addView(text("暂无删除指令",14,MUTED));}button(body,"刷新清单与状态",this::render);}catch(Exception e){notice.setText("无法读取音频管理数据");}}
}
